<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed,watch,nextTick} from 'vue'
import ImageEditor from './ImageEditor.vue'
import DocumentLibrary from './DocumentLibrary.vue'
import Portrait from './Portrait.vue'
import ReviewUnit from './ReviewUnit.vue'
import GroupVisualCard from './GroupVisualCard.vue'
import {visualCards,figureCardAnchor} from './visualGroups'
import AppIcon from './AppIcon.vue'
import {personState,profile,instanceName} from './people'
import {useStudio} from './studioContext'
const props=defineProps<{project:Record<string,any>,studio?:boolean,hideDocuments?:boolean}>();const emit=defineEmits(['replace','running','refresh','confirm-materials'])
const shell=props.studio?useStudio():null,proposalSelection=ref<Record<string,boolean>>({})
const proposal=computed(()=>props.project.visualDetectionProposal?.status==='pending'?props.project.visualDetectionProposal:null)
const rootLocked=(path:string,intersects=false)=>!!shell?.rootLocked(path,intersects)
function replace(value:any){if(mounted&&value.id===props.project.id)emit('replace',value)}
const status=ref<any>({}),tasks=ref<any[]>([]),busy=ref(false),error=ref(''),message=ref(''),documentId=ref(''),page=ref(1),pages=ref('1'),target=ref('background'),selected=ref(''),zoom=ref(100)
const mode=ref('select'),deleted=ref<any>(null),names=ref<Record<string,string>>({}),duplicates=ref<Record<string,boolean>>({}),candidateReview=ref(false)
const kinds:Record<string,string>={background:'历史背景',relationships:'人物与关系',narrative:'已有历史叙事（选填）'}
const doc=computed(()=>props.project.documents?.find((d:any)=>d.id===documentId.value))
const castCharacters=computed(()=>shell?shell.castEntries().map((r:any)=>({...r.draft,id:r.id})):props.project.characters)
const people=computed(()=>props.project.annotations.filter((a:any)=>a.kind==='character'))
const cards=computed(()=>visualCards(props.project,!!props.studio))
const narrativeMode=computed(()=>props.project.materialInputs.narrative.trim()?'保留已有历史叙事框架':'基于历史背景共创故事')
let timer:ReturnType<typeof setInterval>|undefined;let mounted=true;let polling=false
async function request(path:string,method='GET',body?:any){const r=await fetch('/api'+path,{method,headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body instanceof FormData?body:body?JSON.stringify(body):undefined});const v=await r.json();if(!r.ok){const err:any=Error(typeof v.detail==='string'?v.detail:v.detail?.message||JSON.stringify(v.detail));err.detail=v.detail;throw err;}return v}
async function save(){if(shell){await shell.saveAll();return shell.p.value}const p=await request('/projects/'+props.project.id,'PUT',props.project);replace(p);return p}
async function poll(){if(shell||document.hidden||polling)return;polling=true;const pid=props.project.id;try{const previous=tasks.value;const rows=await request(`/projects/${pid}/tasks`);if(!mounted||pid!==props.project.id)return;tasks.value=rows;if(tasks.value.some(t=>t.applied&&previous.find(v=>v.id===t.id)&&!previous.find(v=>v.id===t.id)?.applied)){if(shell)emit('refresh');else replace(await request('/projects/'+pid))}status.value=await request('/status')}catch(e){if(mounted)error.value=String(e)}finally{polling=false}}

async function run(fn:()=>Promise<void>){busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function check(kind:string){await run(async()=>{const r=await request('/models/check','POST',{kind});message.value=r.ok?'连接成功':'未返回有效结果'})}
async function task(kind:string,extra?:any){if(running.value){error.value='本项目已有任务正在运行，请勿重复提交';return}await run(async()=>{const p=await save();const submitted=await request(`/projects/${p.id}/tasks`,'POST',{version:p.version,kind,documentId:documentId.value,pages:pages.value.split(',').map(v=>Number(v.trim())).filter(v=>Number.isInteger(v)&&v>0),trigger:'user_button',autoEnable:true,...extra});tasks.value.unshift(submitted);if(shell)await shell.syncLatest();await poll()})}
function studioGate(){if(props.studio&&(!props.project.image||!Object.values(props.project.materialInputs).some(v=>typeof v==='string'&&v.trim()))){error.value='需要导入古画并填写至少一段资料';return false}return true}
async function upload(e:Event,type:string){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;await run(async()=>{const p=await save();const form=new FormData();form.append('file',f);replace(await request(`/projects/${p.id}/${type}?version=${p.version}`,'POST',form));await poll()})}
async function adopt(legacy=false,updateIds:string[]=[]){await run(async()=>{const p=await save();replace(await request(`/projects/${p.id}/materials/adopt`,'POST',{version:p.version,legacy,updateIds}));message.value='已采用建议，原资料及稳定角色ID保留';candidateReview.value=false})}
function changed(id:string){shell?.scheduleAutosave();const a=props.project.annotations.find((a:any)=>a.id===id);if(a)a.basisChanged=true;for(const o of props.project.observations.filter((o:any)=>o.annotationId===id))o.basisChanged=true;for(const m of props.project.matches.filter((m:any)=>m.annotationId===id))m.basisChanged=true}
function observation(a:any){return props.project.observations.find((o:any)=>o.annotationId===a.id)}
function match(a:any){return props.project.matches.find((m:any)=>m.annotationId===a.id)}
function choose(a:any){a.identityManual=true;const m=match(a);if(m){m.characterId=a.characterId;m.confirmed=false;m.manual=true;m.stale=false}a.identityConfirmed=false;a.needsReview=true}
async function confirm(a:any){await run(async()=>{const p=await save();replace(await request(`/projects/${p.id}/people/${a.id}/confirm`,'POST',{version:p.version,characterId:a.characterId}));message.value='人物资料与姓名对应已确认并保存'})}
function character(a:any){return props.project.characters.find((c:any)=>c.id===a.characterId)}
function remove(){const id=selected.value;const index=props.project.annotations.findIndex((a:any)=>a.id===id);if(index<0)return;deleted.value=JSON.parse(JSON.stringify({annotation:props.project.annotations[index],index,observations:props.project.observations.filter((o:any)=>o.annotationId===id),matches:props.project.matches.filter((m:any)=>m.annotationId===id)}));props.project.annotations.splice(index,1);props.project.observations=props.project.observations.filter((o:any)=>o.annotationId!==id);props.project.matches=props.project.matches.filter((m:any)=>m.annotationId!==id);selected.value=''}
function undo(){if(!deleted.value)return;const d=deleted.value;props.project.annotations.splice(d.index,0,d.annotation);props.project.observations.push(...d.observations);props.project.matches.push(...d.matches);selected.value=d.annotation.id;deleted.value=null}
async function namePerson(a:any,useExisting=false){await run(async()=>{const p=await save();try{replace(await request(`/projects/${p.id}/people/${a.id}/name`,'POST',{version:p.version,name:names.value[a.id]||'',useExisting}));duplicates.value[a.id]=false;names.value[a.id]=''}catch(e:any){if(e.detail?.code==='name_exists'){duplicates.value[a.id]=true;message.value=e.detail.message}else throw e}})}

function confirmObservation(a:any){const o=observation(a);if(o){o.confirmed=a.confirmed;o.description=a.description;o.stale=false}}
function editMaterial(kind?:any){props.project.materialAnalysis.stale=true;if(typeof kind==='string'&&props.project.materialInputOrigins?.[kind])props.project.materialInputOrigins[kind].stale=true}
function insert(text:string){const old=props.project.materialInputs[target.value];props.project.materialInputs[target.value]=old+(old.trim()?'\n\n':'')+text;editMaterial(target.value);message.value='已放入选定输入框，尚未调用模型'}
async function select(id:string,fromCard=false){selected.value=id;if(!fromCard){await nextTick();document.getElementById(figureCardAnchor(cards.value,id))?.scrollIntoView({block:'nearest',behavior:'smooth'})}}
const running=computed(()=>busy.value||(shell?shell.generating.value:tasks.value.some(t=>['queued','running'].includes(t.status))))
watch(busy,v=>emit('running',v),{immediate:true})
watch(()=>props.project.id,()=>{tasks.value=[];selected.value='';documentId.value='';poll()})
watch(()=>proposal.value?.taskId,()=>{proposalSelection.value=Object.fromEntries((proposal.value?.candidates||[]).map((a:any)=>[a.id,true]))},{immediate:true})
async function adoptDetections(){await run(async()=>{const p=await save();const q=p.visualDetectionProposal;const chosen=q.candidates.filter((a:any)=>proposalSelection.value[a.id]);replace(await request(`/projects/${p.id}/detections/adopt`,'POST',{version:p.version,taskId:q.taskId,candidates:chosen}));message.value='补检框已采用。身份匹配仍需点击按钮启动。'})}
onMounted(()=>{if(shell){request('/status').then(value=>{status.value=value}).catch(e=>{error.value=String(e)})}else{poll();timer=setInterval(poll,2500)}});onUnmounted(()=>{mounted=false;clearInterval(timer);emit('running',false)})
function existingCandidate(c:any){return props.project.characters.find((v:any)=>[c.name,c.sourceName].filter(Boolean).some(n=>v.name===n||v.sourceName===n))}
</script>
<template>
<div v-if="error" class="banner error" role="alert">{{error}}</div><div v-if="message" class="banner">{{message}}</div>
<article class="visual-workspace"><div class="actions"><h2>画作与人物</h2><input type="file" :disabled="busy||rootLocked('/annotations',true)" accept="image/png,image/jpeg,image/webp" @change="upload($event,'image')"></div><details><summary>检测与匹配高级操作</summary><div class="actions"><button class="primary" :disabled="running||!project.image" @click="task('detect')">检测人物（本地）</button><button :disabled="running||!project.image" @click="task('supplement')"><AppIcon name="ai" :size="14"/>视觉补检漏检人物</button><button :disabled="running||!people.length||!project.characters.length" @click="task('vision_match')"><AppIcon name="ai" :size="14"/>分析外观并建议身份匹配</button><button :disabled="running||!people.length||!project.characters.length" @click="task('match')"><AppIcon name="ai" :size="14"/>仅重做身份匹配</button></div><small>补检检查全图及最多4个局部区域；匹配分析全图、{{people.length}} 个人物裁切及邻近环境，包含多次调用。采用补框后不会自动匹配。自动身份候选只使用人物档案中“资料描述在画中”的角色；旧资料范围未定时请先核对，人工绑定保持不变。</small></details>
<div class="visual-grid"><div class="canvas-panel"><label>缩放 {{zoom}}%<input type="range" min="50" max="300" v-model.number="zoom"></label><ImageEditor v-if="project.image" :project="project" :zoom="zoom" :selected-id="selected" :disabled="busy||rootLocked('/annotations')" :proposals="proposal?.candidates||[]" :mode="mode" @added="mode='select';shell?.scheduleAutosave()" @select="select($event)" @changed="changed"/><div v-else class="empty">上传画作图片开始</div><details v-if="project.visualOverview"><summary>全图观察与推测</summary><p>{{project.visualOverview.summary}}</p><p v-for="s in project.visualOverview.scenes">{{s.description}}<small>{{s.inference}}</small></p></details></div>
<div class="people-column"><div class="people-toolbar"><b>{{selected?instanceName(project,people.find((a:any)=>a.id===selected)):'人物'}}</b><div class="actions"><button :class="{active:mode==='select'}" @click="mode='select'">选择／调整框</button><button :class="{active:mode==='add'}" @click="mode='add'">新增人物框</button><button :disabled="!selected||rootLocked('/annotations',true)" @click="remove">删除所选框</button><button :disabled="!deleted||rootLocked('/annotations',true)" @click="undo">撤销删除</button><button @click="mode='pan'">平移画作</button></div><small v-if="mode==='add'">在原图拖动绘制漏检人物框。</small></div><div class="person-list"><div v-if="!people.length" class="empty">点击“检测人物”，或在原图拖动补框。</div><template v-for="card in cards" :key="card.id"><GroupVisualCard v-if="card.grouped" :project="project" :card="card" :selected="selected" @select="select($event,true)"/><section v-else v-for="a in card.members" :id="'person-'+a.id" class="person-card" :class="[{chosen:selected===a.id},personState(project,a).key]" @click="select(a.id,true)"><div class="portrait"><Portrait :url="project.image" :box="a"/><small>{{instanceName(project,a)}}</small></div><div class="person-fields"><label>姓名<select :disabled="rootLocked('/annotations/@'+a.id+'/characterId')" v-model="a.characterId" @change="choose(a)"><option value="">未确定／资料未提及</option><option v-if="a.characterId&&!castCharacters.some((c:any)=>c.id===a.characterId)" :value="a.characterId">{{character(a)?.name||'原有对应'}}（保留原有对应）</option><option v-for="c in castCharacters" :value="c.id">{{c.name}}{{c.depictionScope==='background'?'（背景人物）':''}}</option></select></label><p class="profile">{{profile(character(a))}}</p><details v-if="character(a)"><summary>查看原文依据</summary><div v-for="m in character(a).mentions"><small>{{kinds[m.kind]||'原文'}} | 位置 {{m.start}}–{{m.end}}</small><q>{{m.quote}}</q></div><p v-if="!character(a).mentions?.length">{{character(a).evidence||'未提供原文定位；请核对资料。'}}</p></details><ReviewUnit v-if="studio" :unit-id="'visual:'+a.id" label="确认此人物"/><details><summary>直接命名／资料未覆盖的人物</summary><input v-model="names[a.id]" placeholder="输入姓名或角色称谓"><button :disabled="!names[a.id]?.trim()||rootLocked('/annotations/@'+a.id,true)" @click.stop="namePerson(a)">创建并关联</button><div v-if="duplicates[a.id]"><small>已有同名角色。</small><button :disabled="rootLocked('/annotations/@'+a.id,true)" @click.stop="namePerson(a,true)">关联已有角色</button></div></details><label>可见特征<textarea :disabled="rootLocked('/annotations/@'+a.id+'/description')" v-model="a.description" @input="shell?.scheduleAutosave()"/></label><details v-if="observation(a)?.inference"><summary>视觉推测（非历史依据）</summary><p>{{observation(a).inference}}</p></details><details v-if="match(a)"><summary>匹配理由与不确定性</summary><p v-if="match(a).rejectionReason" class="match-conflict">未采用建议：{{match(a).rejectionReason}}</p><p>{{match(a).reason}}</p><div v-if="match(a).conflicts?.length" class="match-conflict"><p v-for="c in match(a).conflicts">{{c}}</p></div><small v-for="ref in match(a).supports">依据：{{ref.quote||ref.text}}</small><small v-if="match(a).confidence">建议把握：{{({high:'较高',medium:'中等',low:'不足'} as any)[match(a).confidence]||match(a).confidence}}</small></details></div></section></template></div></div></div><section v-if="proposal" class="visual-proposals"><div class="rail-heading"><h3>补检人物候选 | {{proposal.candidates.length}}</h3><button :disabled="busy||rootLocked('/visualDetectionProposal')" @click="adoptDetections">采用选中的框</button></div><small>蓝色虚线为补检候选。可调整坐标、删除误检；采用后再手动启动身份匹配。</small><div class="proposal-grid"><div class="proposal-card" v-for="(a,i) in proposal.candidates" :key="a.id"><label><input type="checkbox" v-model="proposalSelection[a.id]">候选 {{Number(i)+1}}</label><Portrait :url="project.image" :box="a"/><small>{{a.description}}</small><details><summary>调整框坐标</summary><div class="compact-grid"><label v-for="field in ['x','y','w','h']">{{field}}<input type="number" min="0" max="1" step="0.005" v-model.number="a[field]"></label></div></details><button @click="proposal.candidates=proposal.candidates.filter((b:any)=>b.id!==a.id)">删除候选</button></div></div></section></article>
<DocumentLibrary v-if="studio&&!hideDocuments"/><article v-if="!studio" class="materials"><h2>资料输入</h2><button :disabled="running" @click="task('materials')"><AppIcon name="ai" :size="14"/>整理资料与角色候选</button><small>重新整理可补充角色称谓、画中范围与原文身份提示；已有角色须查看候选差异后采用更新。</small><div class="material-grid"><label v-for="(name,key) in kinds">{{name}}<textarea rows="9" v-model="project.materialInputs[key]" @input="editMaterial(key)" :placeholder="key==='narrative'?'如果画作有史料记载的故事，请填入事件经过；没有可留空。':'整段粘贴资料，可将出处和链接一并写入。'"/><small v-if="project.materialInputOrigins?.[key]?.stale">该段已修改，原页引用关联需复核；请对照文献原文或重新采用整理摘要。</small></label></div><div class="actions"><button v-if="!studio" class="primary" :disabled="running" @click="studio?emit('confirm-materials'):task('materials')">{{studio?'确认资料并生成文化背景线索':'整理资料并提取人物'}}</button><span class="mode">{{narrativeMode}}</span></div><small>填写已有叙事表示你提供了历史故事框架，不代表系统已经独立核实。留空时，新增故事事件属于共创内容。</small>
<div v-if="project.materialAnalysis.summary" class="card"><fieldset :disabled="rootLocked('/materialAnalysis')"><p>{{project.materialAnalysis.summary}}</p><small v-if="project.materialAnalysis.stale">资料已变化，旧整理结果待复核。点击按钮重新整理。</small><details><summary>查看整理结果与原文片段</summary><p v-for="event in project.materialAnalysis.eventFramework">{{event}}</p><p v-for="s in project.materialSegments"><b>{{kinds[s.kind]}}</b> | {{s.summary}}<small>原文位置 {{s.start}}–{{s.end}}</small><q>{{s.quote}}</q></p></details><button :disabled="running||project.materialAnalysis.stale" @click="candidateReview=!candidateReview">查看人物候选差异并采用</button><div v-if="candidateReview"><div v-for="c in project.materialAnalysis.characters" class="card"><b>{{c.name}}</b><small v-if="c.creativeNaming">创作称谓 | 原文称谓：{{c.creativeNaming.sourceName}}；原文判断保留在依据中。</small><p>{{profile(c)}}</p><template v-if="existingCandidate(c)"><small>现有：{{profile(existingCandidate(c))}}</small><button @click="adopt(false,[existingCandidate(c).id])">采用此人物更新（保留ID）</button></template><small v-else>新增候选人物</small></div><button @click="adopt()">只补充新增人物，保留已有资料</button></div></fieldset></div>
<details v-if="project.sources.some((s:any)=>s.method!=='material_input'&&!s.documentId)"><summary>旧资料与文件原文（保留引用）</summary><button :disabled="running" @click="task('legacy_materials')"><AppIcon name="ai" :size="14"/>整理旧资料到三段输入</button><details v-for="s in project.sources.filter((s:any)=>s.method!=='material_input'&&!s.documentId)" class="card"><summary>{{s.title}}</summary><p class="pre">{{s.text}}</p><small>{{s.citation}}</small></details></details>
<div v-if="project.legacyMaterialProposal" class="card"><h3>三段输入建议</h3><p v-for="(name,key) in kinds"><b>{{name}}</b><br>{{project.legacyMaterialProposal[key]}}</p><small>采用将替换当前三段输入；旧资料和旧引用仍然保留。</small><button @click="adopt(true)">采用这三段建议</button></div>
</article>
<details v-if="!studio" class="document-tools"><summary>从文件辅助填入资料／扫描页 OCR</summary><article><input type="file" accept=".txt,.md,.pdf,.png,.jpg,.jpeg,.webp" @change="upload($event,'documents')"><select v-model="documentId" @change="page=1"><option value="">选择已导入文件</option><option v-for="d in project.documents" :value="d.id">{{d.title}}（{{d.pageCount}}页）</option></select><template v-if="doc"><label>预览页码<input type="number" min="1" :max="doc.pageCount" v-model="page"></label><div class="document-grid"><div><iframe v-if="doc.format==='text'" :src="`/api/projects/${project.id}/documents/${doc.id}/pages/1`" title="原文"/><img v-else class="page-preview" :src="`/api/projects/${project.id}/documents/${doc.id}/pages/${page}`"></div><div><label>放入哪个输入框<select v-model="target"><option v-for="(name,key) in kinds" :value="key">{{name}}</option></select></label><div v-for="s in project.sources.filter((s:any)=>s.documentId===doc.id&&s.page===Number(page))"><textarea rows="10" :disabled="rootLocked('/sources/@'+s.id)" v-model="s.text"/><button @click="insert(s.text)">将此页文本放入选定输入框</button></div><template v-if="doc.format!=='text'"><label>识别页码（逗号分隔，最多20页）<input v-model="pages"></label><small>将执行最多 {{pages.split(',').filter(v=>v.trim()).length}} 次视觉调用，需校对原页。</small><button :disabled="running" @click="task('ocr')">OCR 识别所选页</button></template></div></div></template></article></details>
<div v-for="t in (studio?[]:tasks.slice(0,4))" class="task-row"><b>{{({materials:'资料整理',legacy_materials:'旧资料整理',vision_match:'外观与身份分析',detect:'人物检测',ocr:'文字识别'} as Record<string,string>)[t.kind]||t.kind}}</b> | {{t.progress}}<button v-if="['failed','stale','interrupted'].includes(t.status)" :disabled="running" @click="task(t.kind,{documentId:t.request.documentId,pages:t.request.pages})">重试 | {{t.kind==='detect'?'本地模型':'调用 LLM'}}</button></div>
<details class="settings"><summary>模型设置与连通性测试</summary><small>文本 {{status.textModel}} | 视觉 {{status.visionModel}} | 检测器 {{status.detectorLoaded?'已加载':status.detectorCached?'已缓存':'未加载'}}。测试按钮会发送真实请求。</small><div class="actions"><button :disabled="running" @click="check('text')"><AppIcon name="ai" :size="14"/>测试文本模型</button><button :disabled="running" @click="check('vision')"><AppIcon name="ai" :size="14"/>测试视觉模型</button></div></details>
</template>
